def hero(eyebrow,h1,lead,img,alt,extra=""):
    return f'''<section class="hero"><div class="hero-grid"><div>
<p class="eyebrow">{eyebrow}</p><h1>{h1}</h1><p class="lead">{lead}</p>{extra or ctas()}</div>
<figure class="hero-photo"><img src="/images/{img}" alt="{alt}" width="640" height="800" loading="eager"></figure></div></section>'''
def sec(h2,body,cls="blk"): return f'<section class="{cls}"><h2>{h2}</h2>{body}</section>'
def ps(*t): return "".join(f"<p>{x}</p>" for x in t)
def rows(items):  # [(title, text)]
    return '<ol class="rows">'+"".join(f'<li><h3>{a}</h3><p>{b}</p></li>' for a,b in items)+'</ol>'
def ul(items,cls="signs"): return f'<ul class="{cls}">'+"".join(f"<li>{x}</li>" for x in items)+'</ul>'
def faq(items): return '<div class="faq">'+"".join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def pull(t): return f'<div class="pull-quote">{t}</div>'
def band(h,p,extra=None):
    return f'<div class="ctaband"><h2>{h}</h2><p>{p}</p>{extra or ctas()}</div>'
def tool(n,t,body): return f'<li><h3>{n}. {t}</h3><p>{body}</p></li>'
def tools(items,h2="כלים לתרגול — אפשר להתחיל מהיום"):
    return sec(h2,'<ol class="rows">'+"".join(tool(i+1,a,b) for i,(a,b) in enumerate(items))+'</ol>'+'<p class="note">הכלים האלה הם התחלה, ולא תחליף לליווי אישי. אם משהו מציף או מעורר מצוקה, עוצרים וחוזרים לנשימה טבעית.</p>')
def cure_row(): return '<ol class="cure-row" aria-label="ארבעת שלבי CURE"><li><b>C</b>Clarity<span>בהירות</span></li><li><b>U</b>Unblock<span>שחרור</span></li><li><b>R</b>Rewire<span>חיווט מחדש</span></li><li><b>E</b>Empower<span>העצמה</span></li></ol>'
def where(): return ul(["קריית מוצקין, מרכז דיאלוג","קריית חיים, מרכז תכלת","בזום, לכל הארץ"],"chips")
def related(links): return '<nav class="related" aria-label="עמודים קשורים"><span>עוד באתר:</span>'+"".join(f'<a href="{h}">{t}</a>' for h,t in links)+'</nav>'
def disc(long=False): return f'<div class="disclaimer">{DISC_LONG if long else DISC}</div>'

