# ================= render =================
def render(fn,url,title,desc,main,ld,og_img):
    s=pre
    s=re.sub(r'<title>.*?</title>',f'<title>{e(title)}</title>',s,flags=re.S)
    s=re.sub(r'<meta name="description" content="[^"]*"\s*/?>',f'<meta name="description" content="{e(desc)}" />',s)
    s=re.sub(r'<link rel="canonical" href="[^"]*"\s*/?>',f'<link rel="canonical" href="{BASE}{url}" />',s)
    s=re.sub(r'<meta property="og:title" content="[^"]*"\s*/?>',f'<meta property="og:title" content="{e(title)}" />',s)
    s=re.sub(r'<meta property="og:description" content="[^"]*"\s*/?>',f'<meta property="og:description" content="{e(desc)}" />',s)
    s=re.sub(r'<meta property="og:url" content="[^"]*"\s*/?>',f'<meta property="og:url" content="{BASE}{url}" />',s)
    s=re.sub(r'<script type="application/ld\+json">.*?</script>\s*','',s,flags=re.S)
    bc={"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"בית","item":BASE+"/"},{"@type":"ListItem","position":2,"name":title.split(" | ")[0].split(" — ")[0],"item":BASE+url}]}
    lds="".join(f'<script type="application/ld+json">{json.dumps(x,ensure_ascii=False)}</script>\n' for x in [bc]+ld)
    s=s.replace("</head>",lds+"</head>",1)
    body=f'<main class="wrap" data-sc-in data-sc-stagger="70">\n{main}\n</main>'
    post2=post.replace('</body>','<script src="/online.js" defer></script></body>',1) if fn=='online.html' else post
    out=s+body+post2
    open(fn,"w",encoding="utf8").write(out)
for fn,(url,title,desc,main,ld,og) in PAGES.items(): render(fn,url,title,desc,main,ld,og); print("built",fn)
